import { Scene, Circle, CameraModel, hex } from 'retiam';
export default class MeterScene extends Scene {
  private circle?: Circle;
  private amount = 0.5;
  setAmount(value: number) {
    this.amount = Math.max(0.05, Math.min(1, value));
    this.circle?.setScale(this.amount);
    this.invalidate();
  }
  async run() {
    this.clearColor(hex('#080c14'));
    this.camera.model = CameraModel.ORTHOGRAPHIC;
    this.camera.orthoScale = 5;
    this.camera.position.set([0, 0, 20]);
    this.camera.lookAt([0, 0, 0]);
    this.circle = new Circle(1.5, { fill: hex('#38bdf8') });
    this.add(this.circle);
    this.setAmount(this.amount);
  }
}

import { useEffect, useRef, useState } from 'react';
import MeterScene from './MeterScene';

export function RetiamPreview({ amount }: { amount: number }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sceneRef = useRef<MeterScene | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current!;
    const scene = new MeterScene();
    sceneRef.current = scene;
    let cancelled = false, started = false, resizeFrame = 0;
    let observer: ResizeObserver | undefined;
    void scene.start(canvas).then(() => {
      started = true;
      if (cancelled) { scene.destroy(); return; }
      observer = new ResizeObserver(() => {
        cancelAnimationFrame(resizeFrame);
        resizeFrame = requestAnimationFrame(() => {
          window.dispatchEvent(new Event('resize'));
          scene.invalidate();
        });
      });
      observer.observe(canvas.parentElement!);
    }).catch(cause => {
      scene.destroy();
      if (!cancelled) setError(String(cause));
    });
    return () => {
      cancelled = true;
      observer?.disconnect(); cancelAnimationFrame(resizeFrame);
      if (sceneRef.current === scene) sceneRef.current = null;
      if (started) scene.destroy();
      // If initialization is pending, its continuation performs cleanup.
    };
  }, []);

  useEffect(() => { sceneRef.current?.setAmount(amount); }, [amount]);
  return <div style={{ height: 360, width: '100%', position: 'relative' }}>
    <canvas ref={canvasRef} style={{ display: 'block', width: '100%', height: '100%' }} />
    {error && <p role="alert">{error}</p>}
  </div>;
}

import { StrictMode, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { RetiamPreview } from './RetiamPreview';
function App() {
  const [amount, setAmount] = useState(0.5);
  return <>
    <input aria-label="Circle scale" type="range" min="0.05" max="1" step="0.01"
      value={amount} onChange={event => setAmount(Number(event.target.value))} />
    <RetiamPreview amount={amount} />
  </>;
}
createRoot(document.getElementById('root')!).render(<StrictMode><App /></StrictMode>);
